import { Request, Response } from "express";
import { AddTaskUseCase } from "../application/add-task-use-case";
import { AssignTaskUseCase } from "../application/assign-task-use-case";
import { ListProjectTasksUseCase } from "../application/list-project-tasks-use-case";
import { MarkTaskDoneUseCase } from "../application/mark-task-done-use-case";
import { parseTaskStatus } from "../domain/task-status";
import { asBody, optionalString, requireString } from "./request-parsing";

export class TaskController {
  constructor(
    private readonly addTask: AddTaskUseCase,
    private readonly assignTask: AssignTaskUseCase,
    private readonly listTasks: ListProjectTasksUseCase,
    private readonly markTaskDone: MarkTaskDoneUseCase,
  ) {}

  add = async (req: Request, res: Response): Promise<void> => {
    const body = asBody(req.body);
    const task = await this.addTask.execute({
      projectId: String(req.params.projectId),
      title: requireString(body.title, "title"),
      description: optionalString(body.description, "description") ?? "",
      dueDate: optionalString(body.dueDate, "dueDate"),
      status: body.status === undefined ? undefined : parseTaskStatus(body.status),
    });
    res.status(201).json(task);
  };

  list = async (req: Request, res: Response): Promise<void> => {
    const { status, assigneeId } = req.query;
    const tasks = await this.listTasks.execute({
      projectId: String(req.params.projectId),
      status: status === undefined ? undefined : parseTaskStatus(status),
      assigneeId: optionalString(assigneeId, "assigneeId"),
    });
    res.json(tasks);
  };

  assign = async (req: Request, res: Response): Promise<void> => {
    const body = asBody(req.body);
    const task = await this.assignTask.execute({
      taskId: String(req.params.taskId),
      userId: requireString(body.userId, "userId"),
    });
    res.json(task);
  };

  markDone = async (req: Request, res: Response): Promise<void> => {
    res.json(await this.markTaskDone.execute(String(req.params.taskId)));
  };
}

